import{_ as o,o as t,c,a0 as i}from"./chunks/framework.CNDWyMYS.js";const p=JSON.parse('{"title":"Rock file format","description":"","frontmatter":{},"headers":[],"relativePath":"rock_file_format.md","filePath":"rock_file_format.md"}'),r={name:"rock_file_format.md"};function a(l,e,s,n,d,u){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="rock-file-format" tabindex="-1">Rock file format <a class="header-anchor" href="#rock-file-format" aria-label="Permalink to &quot;Rock file format&quot;">​</a></h1><p>This page describes the .rock file format used by LuaRocks.</p><p>Note that there are different <a href="./types_of_rocks.html">types of rocks</a>.</p><h2 id="filenames" tabindex="-1">Filenames <a class="header-anchor" href="#filenames" aria-label="Permalink to &quot;Filenames&quot;">​</a></h2><ul><li><p>.rock and .rockspec filenames must be all-lowercase</p></li><li><p>Rock names must follow the format &quot;$NAME-$VERSION-$REVISION.$PLATFORM.rock&quot;, where:</p></li><li><p>$NAME is an arbitrary name (matchable via <code>&quot;[a-z0-9_-]+&quot;</code>)</p></li><li><p>$VERSION is a version number parseable by LuaRocks (e.g. &quot;1.0&quot;, &quot;2.1beta1&quot;, &quot;scm&quot; for git-HEAD/svn-master rockspecs)</p></li><li><p>$REVISION is the rockspec revision number, a positive integer</p></li><li><p>$PLATFORM must follow the format &quot;$OS-$ARCH&quot;, where:</p><ul><li>$OS is an operating system identifier known by LuaRocks</li><li>$ARCH is a hardware architecture identifier known by LuaRocks</li></ul></li></ul><h2 id="source-rocks" tabindex="-1">Source rocks <a class="header-anchor" href="#source-rocks" aria-label="Permalink to &quot;Source rocks&quot;">​</a></h2><p>A source rock must contain at its root the rockspec file. For a rock called <code>myrock-1.0-1.src.rock</code> it would be called:</p><ul><li><code>myrock-1.0-1.rockspec</code> - the [rockspec file](Rockspec format) in the archive root</li></ul><p>Additionally, it must contain the sources:</p><ul><li>If the <code>source.url</code> field is specified using a file download protocol-type URL (<code>http://</code>, <code>https://</code>, <code>file://</code> and so on) pointing to the source archive (or source file in case of a single-file rock), the rock should contain the product of downloading this URL. <ul><li>For example, a source rock may contain two files: <code>myrock-1.0-1.rockspec</code> and <code>myrock-1.0.tar.gz</code></li></ul></li><li>If the <code>source.url</code> field is specified using a Source Control Manager (SCM) protocol-type URL (<code>git://</code>, <code>hg://</code>, <code>svn://</code> and so on), the rock should contain the corresponding checked-out sources. The SCM metadata (e.g. the <code>.git</code> directory) does not need to be present. (Note: This is not specific to &quot;scm&quot; rocks that point to in-development repositories; a stable-version rockspec may use a SCM-based URL and an SCM tag with <code>source.tag</code> in the rockspec to point to a release version). <ul><li>For example, a source rock may contain at the root the rockspec <code>myrock-1.0-1.rockspec</code> and a directory <code>myrock</code> that would be the result of <code>git clone https://github.com/example/myrock</code></li></ul></li></ul><h2 id="binary-rocks" tabindex="-1">Binary rocks <a class="header-anchor" href="#binary-rocks" aria-label="Permalink to &quot;Binary rocks&quot;">​</a></h2><p>A binary rock must contain at its root two files. For a rock called <code>myrock-1.0-1.linux-x86.rock</code> they would be called:</p><ul><li><code>myrock-1.0-1.rockspec</code> - the <a href="./rockspec_format.html">rockspec file</a> in the archive root</li><li><code>rock_manifest</code> - a <a href="./rock_manifest_file_format.html">rock manifest file</a></li></ul><p>These standard directories are handled specially:</p><ul><li><code>lib/</code> - a directory containing binary modules (the contents of this directory are files that go into <code>$PREFIX/lib/lua/5.x/</code> in a vanilla Lua installation on Unix). The directory structure inside this directory is replicated when installing.</li><li><code>lua/</code> - a directory containing Lua modules (the contents of this directory are files that go into <code>$PREFIX/share/lua/5.x/</code> in a vanilla Lua installation on Unix). The directory structure inside this directory is replicated when installing.</li><li><code>bin/</code> - a directory containing executable Lua scripts (the contents of this directory are files that go into <code>$PREFIX/bin/</code> in a vanilla Lua installation on Unix)</li><li><code>doc/</code> or <code>docs/</code> - documentation files - if present, their contents are listed when running <code>luarocks doc</code>. The directory structure inside this directory is replicated when installing.</li></ul><p>Any additional directories in the .rock file are copied verbatim (including subdirectories) to <code>$ROCK_TREE/lib/luarocks/rocks-5.x/myrock/1.0-1/</code> (common directories are <code>tests</code>, <code>samples</code>, <code>examples</code>, etc.</p><h3 id="pure-lua-rocks" tabindex="-1">Pure-Lua rocks <a class="header-anchor" href="#pure-lua-rocks" aria-label="Permalink to &quot;Pure-Lua rocks&quot;">​</a></h3><p>Pure-Lua rocks are identical to binary rocks, except that they don&#39;t have a <code>lib/</code> directory containing binary modules. When a rock contains only <code>lua/</code> files and no <code>lib/</code> files, it automatically gains the <code>.all.rock</code> file extension. If the rock is platform-specific, the packager may rename the file to the proper platform, or specify the list of supported platforms in the <code>supported_platforms</code> table of the rockspec.</p>',18)])])}const f=o(r,[["render",a]]);export{p as __pageData,f as default};
